<?php
if(getenv('DGS_TEST_ALLOW_FIXTURES')!=='1'||empty($argv[1]))exit(2);require $argv[1];wp_set_current_user(get_user_by('login','showcase_local_admin')->ID);ob_start();dgt_logo();$logo=ob_get_clean();ob_start();dgt_navigation();$public=ob_get_clean();$manager=dgs_panel_menu_html();foreach(['public'=>$public,'manager'=>$manager] as $kind=>$nav){$html='<html dir="rtl"><body class="dg-site'.($kind==='manager'?' dgs-role-portal admin-bar':'').'"><div class="dg-shell"><aside id="dg-sidebar" class="dg-sidebar"><div class="dg-sidebar-brand">'.$logo.'</div><nav>'.$nav.'</nav><div class="dg-sidebar-bottom">پایه‌های دهم، یازدهم و دوازدهم</div></aside><div class="dg-backdrop" hidden onclick="document.body.classList.remove(\'dg-menu-open\');this.hidden=true;document.querySelector(\'.dg-mobile-toggle\').setAttribute(\'aria-expanded\',\'false\')"></div><div class="dg-page"><button class="dg-mobile-toggle" aria-expanded="false" onclick="document.body.classList.toggle(\'dg-menu-open\');this.setAttribute(\'aria-expanded\',document.body.classList.contains(\'dg-menu-open\')?\'true\':\'false\');document.querySelector(\'.dg-backdrop\').hidden=!document.body.classList.contains(\'dg-menu-open\')">بازکردن منو</button><main style="min-height:3000px">محتوای صفحه</main></div></div></body></html>';file_put_contents('/tmp/mobile-'.$kind.'.html',$html);}echo "Public and manager fixtures rendered\n";
